sys_variable_value.value:
(function execute(inputs, outputs) {
    var body = JSON.parse(inputs.response_body || '{}');
    var users = body.Users || [];

    // Map email (lowercase) -> Xero ID, same rule as Get User: GlobalUserID, otherwise UserID
    var byEmail = {};
    for (var i = 0; i < users.length; i++) {
        var u = users[i];
        if (u.EmailAddress) {
            byEmail[u.EmailAddress.toLowerCase()] = u.GlobalUserID || u.UserID;
        }
    }

    // Retry only the users still marked as Not found
    var matched = 0, notFound = 0;
    var now = new GlideDateTime();
    var map = new GlideRecord('x_snc_spm_xero_i_0_external_user_mapping');
    map.addQuery('tool', 'xero');
    map.addQuery('status', 'not_found');
    map.query();

    while (map.next()) {
        var email = (map.user.email + '').toLowerCase();
        map.setValue('email', map.user.email + '');
        map.setValue('last_checked', now);
        if (byEmail[email]) {
            // Found in Xero: store the ID, mark as Matched and clear the message
            map.setValue('external_id', byEmail[email]);
            map.setValue('status', 'matched');
            map.setValue('message', '');
            matched++;
        } else {
            // Still not in Xero: stays Not found and is retried on the next run
            map.setValue('message', 'Email not found in Xero');
            notFound++;
        }
        map.update();
    }

    outputs.matched_count = matched;
    outputs.not_found_count = notFound;
})(inputs, outputs);

